#include <iostream>
#include <cmath>
#include <iomanip>

class Point {
private:
    double x;
    double y;

public:
    Point(double xVal = 0.0, double yVal = 0.0) : x(xVal), y(yVal) {}

    double distanceTo(const Point& d2) const {
        // Su dung *this de truy xuat doi tuong hien tai
        const Point& d1 = *this;
        return std::sqrt(std::pow(d1.x - d2.x, 2) + std::pow(d1.y - d2.y, 2));
    }

    double perimeter(const Point& d2, const Point& d3) const {
        // Tai su dung phuong thuc distanceTo giua cac dinh
        double side1 = this->distanceTo(d2);
        double side2 = distanceTo(d3);
        double side3 = d2.distanceTo(d3);
        return side1 + side2 + side3;
    }
};

int main() {
    Point d1(0.0, 0.0);
    Point d2(3.0, 0.0);
    Point d3(0.0, 4.0);

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Distance d1 to d2: " << d1.distanceTo(d2) << "\n";
    std::cout << "Distance d2 to d3: " << d2.distanceTo(d3) << "\n";
    std::cout << "Distance d1 to d3: " << d1.distanceTo(d3) << "\n";
    std::cout << "Triangle perimeter: " << d1.perimeter(d2, d3) << "\n";

    return 0;
}
